const sitarAt = x => notesAt(SITAR, x)
const lastOf = (list, x) => { let lo = 0, hi = list.length - 1, k = -1; while (lo <= hi) { const m = (lo + hi) >> 1; if (list[m][0] <= x) (k = m), (lo = m + 1); else hi = m - 1 } return k }

// ---- sitar -------------------------------------------------------------------------------------
const track0 = {
  color: '#ffb060',
  graph: x => { const m = sitarAt(x); return m ? 0.8 + (m.n + 12) * 0.06 : null },
  midi: x => { const m = sitarAt(x); return m && m.u < 0.9 ? [SA + m.n] : [] },
  formula: ["Si = 0.55x + 0.6\\BP_{180}x + 0.35\\BP_{2400}x + \\textstyle\\sum_j \\BP^{Q=60}_{f_j}x,\\quad x:\\ D(t) = \\big(\\tfrac{SR}{f} - \\varphi\\big)\\big(1 - 0.03\\max(0, y)\\big)","\\text{джавари укорачивает струну на одной стороне колебания (жужжание); } f_j \\text{ — тараб: ноты раги; мінд — } f\\cdot 2^{\\,m(1 - s(t))/12}"],
  audio({ bpm }) {
    const sec = 60 / bpm, s = sitar({ tarab: [62,63,66,67,69,70,73,74].map(m => hz(m - 60, C4)) }), fire = trigger(), verb = reverb({ room: 0.8, damp: 0.4, wet: 0.3 })
    return x => {
      const k = lastOf(SITAR, x), m = k >= 0 && x < SITAR[k][0] + SITAR[k][2] + 2 ? SITAR[k] : null
      if (m && fire(k)) {
        const o = ORN.get(k), d = m[2] * sec
        s.hit(sw(m[1]), 0.75 + 0.15 * hash(k, 3), o ? { from: o.meend, glide: 0.12, ...(o.andolan ? { bend: -0.3, bendAt: 0.25 * d, bendTime: 0.35 * d, back: 0.65 * d } : {}) } : {})
      }
      return verb(...pan(0.5 * s(), -0.1))
    }
  },
}

